import dotenv from "dotenv"
import { readFileSync } from "node:fs"
import { fileURLToPath } from "node:url"
import { defineConfig } from "prisma/config"
import { discoverWorkspaceEnvFile, isBorrowedWorkspaceEnvFile } from "../../scripts/workspace-env.js"

const prismaConfigDir = fileURLToPath(new URL(".", import.meta.url))
const envFile = discoverWorkspaceEnvFile({ cwd: prismaConfigDir })
if (envFile) {
  const values = dotenv.parse(readFileSync(envFile))
  // Never point a worktree's Prisma commands at the main checkout's database.
  if (isBorrowedWorkspaceEnvFile(envFile, { cwd: prismaConfigDir })) delete values.DATABASE_URL
  dotenv.populate(process.env, values)
}

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env["DATABASE_URL"],
  },
})
